UPDATE products.products
SET name      = #{name},
    price     = #{price},
    stock     = #{stock},
    version   = version + 1,
    update_at = #{updateAt}

    , updated_by = #{updatedBy}

WHERE id = #{id}
  AND version = #{version}
  AND is_delete = false

UPDATE products.products
SET is_delete = true,
    update_at = #{now}

    , updated_by = #{updatedBy}

WHERE id = #{id}
  AND is_delete = false

UPDATE products.products
SET is_delete = true,
    update_at = #{now}

    , updated_by = #{updatedBy}

WHERE is_delete = false
  AND id IN
#{id}

mapper.select:
SELECT EXISTS (
    SELECT 1 FROM products.products WHERE id = #{id} AND is_delete = false
